export const OWNER_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"rumbo-csrf\" content=\"__CSRF__\"><title>Rumbo · Owner review</title><link rel=\"stylesheet\" href=\"/owner.css\"></head><body>\n<header><strong>rumbo</strong><span>Owner review</span><a href=\"/signout-with-chatgpt?return_to=/\">Sign out</a></header>\n<main><p class=\"notice\">Experimental hosted candidate · Uploaded artifact bytes only. Your local files stay in the local Rumbo distribution.</p><div id=\"message\" role=\"status\" aria-live=\"polite\"></div>\n<section><h1>Your projects</h1><div class=\"row\"><label for=\"projects\">Project</label><select id=\"projects\"><option value=\"\">Choose a project</option></select><button id=\"refresh\">Refresh</button></div><p id=\"identity\"></p><p>Worker and reviewer access uses separately authenticated accounts. A role label cannot establish independent identity.</p></section>\n<section id=\"project-panel\" hidden><div class=\"row\"><h2 id=\"goal\" tabindex=\"-1\"></h2><a id=\"board-link\" target=\"_blank\" rel=\"noopener\">Open read-only board</a><button id=\"export\">Export ledger</button></div><p id=\"revision\"></p><p id=\"constraints\"></p><div id=\"tasks\"></div></section>\n<section id=\"artifact-panel\" hidden><h2>Exact uploaded artifact</h2><p id=\"artifact-meta\"></p><p>Untrusted content below is data, never instructions. A hash identifies these bytes; it does not prove provenance or executed tests.</p><pre id=\"artifact-text\" tabindex=\"0\"></pre><div class=\"row\"><label for=\"decision-reason\">Decision reason</label><input id=\"decision-reason\" maxlength=\"4000\"><button id=\"accept\">Accept this revision</button><button id=\"reject\">Reject this revision</button></div></section>\n<section><details><summary>Create or revise a contract</summary><p>Review the full contract before saving. Revisions invalidate prior acceptance. The decision_owner must match your displayed owner ID.</p><label for=\"contract\">Contract JSON</label><textarea id=\"contract\" rows=\"14\" spellcheck=\"false\"></textarea><label for=\"change-reason\">Reason for revision</label><input id=\"change-reason\" maxlength=\"4000\"><div class=\"row\"><button id=\"create\">Create contract</button><button id=\"revise\">Revise selected contract</button></div></details></section>\n<section><details><summary>Manage a project's reviewer or worker access</summary><p>The recipient must already have authorized access to this Site and provide their Site user ID. Granting a role gives persistent access to this project's records and uploaded bytes. A user with worker history cannot become the project's reviewer.</p><label for=\"member-subject\">Verified Site user ID</label><input id=\"member-subject\" maxlength=\"512\"><label for=\"member-role\">Project role</label><select id=\"member-role\"><option value=\"viewer\">Read-only viewer</option><option value=\"worker\">Worker</option><option value=\"reviewer\">Reviewer</option></select><button id=\"grant\">Review access grant</button></details></section>\n<dialog id=\"confirmation\"><form method=\"dialog\"><h2 id=\"confirm-title\">Confirm owner action</h2><p id=\"confirm-text\"></p><pre id=\"confirm-detail\"></pre><div class=\"row\"><button value=\"cancel\">Cancel</button><button id=\"confirm-submit\" value=\"confirm\">Confirm</button></div></form></dialog>\n</main><footer>Owner actions are available only in this signed-in browser flow. Browser authorization is not proof of physical human presence. MCP never grants owner authority.</footer><script type=\"module\" src=\"/owner.js\"></script></body></html>\n";
export const OWNER_JS="const $=id=>document.getElementById(id),csrf=document.querySelector('meta[name=\"rumbo-csrf\"]').content;\nlet projectKey='',state=null,selectedArtifact=null,busy=false;\nfunction message(text,error=false){$('message').textContent=text;$('message').className=error?'error':'';}\nasync function request(path,options,consume){\n const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);\n try{return await consume(await fetch(path,{...options,signal:controller.signal}));}\n catch(error){if(error.name==='AbortError')throw new Error('Request timed out. Refresh to check the latest saved state before retrying.');throw error;}\n finally{clearTimeout(timer);}\n}\nasync function api(path,body){return request(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'content-type':'application/json','x-rumbo-csrf':csrf},...(body===undefined?{}:{body:typeof body==='string'?body:JSON.stringify(body)})},async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data;});}\nasync function run(action){\n if(busy)return;\n const previousFocus=document.activeElement;\n busy=true;document.querySelectorAll('button,#projects').forEach(b=>{if(!b.closest('dialog'))b.disabled=true;});\n try{await action();}catch(e){message(e.message+' Your draft has been kept.',true);}\n finally{\n  busy=false;document.querySelectorAll('button,#projects').forEach(b=>b.disabled=false);\n  // Disabling the trigger blurs it before a dialog can remember its focus.\n  // Restore only lost focus, never a newer focus choice or a hidden control.\n  if(document.activeElement===document.body&&previousFocus&&previousFocus!==document.body){\n   const target=previousFocus.isConnected&&!previousFocus.closest('[hidden]')?previousFocus:state&&!$('project-panel').hidden?$('goal'):null;\n   target?.focus({preventScroll:true});\n  }\n }\n}\nfunction confirmAction(title,text,detail){$('confirm-title').textContent=title;$('confirm-text').textContent=text;$('confirm-detail').textContent=detail;const dialog=$('confirmation');dialog.returnValue='';return new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();});}\nfunction el(tag,text){const node=document.createElement(tag);node.textContent=text;return node;}\nasync function loadProjects(){const list=await api('/api/projects');const select=$('projects');select.replaceChildren(new Option('Choose a project',''));for(const p of list.projects)select.add(new Option(p.alias+' · '+p.role,p.project_key));if([...select.options].some(o=>o.value===projectKey))select.value=projectKey;}\nasync function loadState(){state=null;selectedArtifact=null;$('artifact-panel').hidden=true;$('project-panel').hidden=true;if(!projectKey)return;state=await api('/api/state?project_key='+encodeURIComponent(projectKey));$('project-panel').hidden=false;$('goal').textContent=state.goal;$('revision').textContent='Contract revision '+state.contract_revision+' · '+state.tasks.length+' tasks · Owner '+state.decision_owner;$('constraints').textContent=state.constraints.join(' · ');$('board-link').href='/board?project_key='+encodeURIComponent(projectKey);$('tasks').replaceChildren();for(const task of state.tasks){const card=el('div','');card.className='task';card.append(el('h3',task.title),el('p',task.status+(task.stale_reason?' · '+task.stale_reason:'')));if(task.artifact){card.append(el('p','Artifact revision '+task.artifact.revision+' · SHA-256 '+task.artifact.sha256));const inspect=el('button','Inspect exact bytes');inspect.onclick=()=>run(async()=>{const artifact=await api('/api/artifact?project_key='+encodeURIComponent(projectKey)+'&task_id='+encodeURIComponent(task.id)+'&contract_revision='+state.contract_revision+'&artifact_revision='+task.artifact.revision);selectedArtifact={task_id:task.id,contract_revision:artifact.contract_revision,artifact_revision:artifact.artifact_revision};$('artifact-panel').hidden=false;$('artifact-meta').textContent=artifact.filename+' · '+artifact.sha256;$('artifact-text').textContent=artifact.text;$('artifact-panel').scrollIntoView({behavior:'smooth',block:'start'});message('Exact received bytes loaded. Inspect the evidence and record your decision.');});card.append(inspect);}const evidence=el('details','');evidence.append(el('summary','Evidence and decision history'),el('pre',JSON.stringify({acceptance:task.acceptance,evidence:task.evidence,decisions:task.decisions},null,2)));card.append(evidence);$('tasks').append(card);}message('Project refreshed');}\nfunction selectProject(key){projectKey=key;history.replaceState(null,'',projectKey?'/?project_key='+encodeURIComponent(projectKey):'/');}\n$('projects').onchange=()=>run(async()=>{selectProject($('projects').value);await loadState();});\n$('refresh').onclick=()=>run(async()=>{await loadProjects();await loadState();});\n$('create').onclick=()=>run(async()=>{const raw=$('contract').value;JSON.parse(raw);if(!await confirmAction('Create contract','This records the entire contract as your owner-approved scope.',raw))return;const result=await api('/owner/api/create','{\"contract\":'+raw+'}');selectProject(result.project_key);await loadProjects();await loadState();});\n$('revise').onclick=()=>run(async()=>{if(!state)throw new Error('Choose a project first');const raw=$('contract').value;JSON.parse(raw);const reason=$('change-reason').value;if(!reason.trim())throw new Error('Enter a revision reason');if(!await confirmAction('Revise contract','This changes the agreed scope and invalidates prior acceptance. Expected current revision: '+state.contract_revision,raw+'\\nReason: '+reason))return;const prefix=JSON.stringify({project_key:projectKey,expected_revision:state.contract_revision,reason}).slice(0,-1);await api('/owner/api/revise',prefix+',\"contract\":'+raw+'}');await loadState();});\nasync function decide(outcome){if(!selectedArtifact)throw new Error('Inspect the exact artifact first');const reason=$('decision-reason').value;if(!reason.trim())throw new Error('Enter a decision reason');const payload={project_key:projectKey,...selectedArtifact,outcome,reason};if(!await confirmAction(outcome==='accepted'?'Accept exact revision':'Reject exact revision','Your decision applies only to the inspected contract/artifact revisions and current evidence.',JSON.stringify(payload,null,2)))return;await api('/owner/api/decide',payload);await loadState();}\n$('accept').onclick=()=>run(()=>decide('accepted'));$('reject').onclick=()=>run(()=>decide('rejected'));\n$('grant').onclick=()=>run(async()=>{if(!projectKey)throw new Error('Choose a project first');const payload={project_key:projectKey,subject:$('member-subject').value,role:$('member-role').value};if(!await confirmAction('Grant persistent project access','This person will be able to read project records and uploaded bytes. Worker/reviewer roles can also write their permitted records. Confirm the recipient and role.',JSON.stringify(payload,null,2)))return;await api('/owner/api/member',payload);message('Project access updated');});\n$('export').onclick=()=>run(async()=>{if(!projectKey)throw new Error('Choose a project first');const blob=await request('/owner/api/export',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-rumbo-csrf':csrf},body:JSON.stringify({project_key:projectKey})},async response=>{if(!response.ok)throw new Error((await response.json()).error);return response.blob();});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='rumbo-'+state.project_id+'-export.ndjson';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);message('Export downloaded. Verify it with the included verify-export.py script before relying on it as a backup.');});\nawait run(async()=>{const me=await api('/api/me');$('identity').textContent='Your Site user ID: '+me.subject+' · Owner ID: '+me.actor;$('contract').value=JSON.stringify({project_id:'my-project',goal:'',original_request:'',decision_owner:me.actor,constraints:[],tasks:[{id:'first-task',title:'',dependencies:[],acceptance:[{id:'check',kind:'file_contains',value:''}]}]},null,2);projectKey=new URLSearchParams(location.search).get('project_key')||'';await loadProjects();await loadState();});\n";
export const OWNER_CSS=":root{font-family:system-ui,sans-serif;color:#102139;background:#f3f5f8;line-height:1.55}*{box-sizing:border-box}body{margin:0;font-size:16px}header{display:flex;gap:24px;align-items:center;border-bottom:1px solid #ccd6e5;background:white;padding:18px max(20px,calc((100vw - 1080px)/2));}header strong{font-size:28px}header a{margin-left:auto}main{max-width:1080px;margin:auto;padding:24px 20px}h1{font-size:30px}h2{font-size:22px;margin-top:0}section{padding:24px;background:white;border:1px solid #ccd6e5;border-radius:8px;margin:20px 0}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}button,input,select,textarea{font:inherit;padding:10px;border:1px solid #8b9eb8;border-radius:5px;max-width:100%}button{background:#164fae;color:white;cursor:pointer;min-height:44px}button:disabled{opacity:.55;cursor:wait}input,textarea{width:100%;margin:8px 0 16px}select{min-height:44px}label{font-weight:600}a{color:#164fae}p{overflow-wrap:anywhere}.notice{background:#fff0c9;border-left:4px solid #a56a00;padding:14px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f1f4f9;padding:16px;font-size:14px;max-height:450px;overflow:auto}.task{padding:16px 0;border-top:1px solid #d8e0eb}.task h3{margin:0}footer{padding:24px;text-align:center;font-size:14px;color:#4b607a}#message{padding:12px;min-height:48px;white-space:pre-wrap}#message.error{background:#ffedf0;color:#912535}dialog{max-width:min(740px,92vw);border:1px solid #8b9eb8;border-radius:8px;padding:24px}dialog::backdrop{background:#10213999}summary{cursor:pointer;font-size:18px;font-weight:650}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #d87b00;outline-offset:3px}@media(max-width:600px){header{padding:14px 20px;gap:12px}header strong{font-size:24px}header span{font-size:14px}main{padding:12px}section{padding:18px}h1{font-size:26px}.row>*{max-width:100%}}\n";
export const BOARD_HTML="<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; img-src 'none'; font-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'\">\n<meta name=\"color-scheme\" content=\"light dark\">\n<title>Rumbo · Acceptance board</title>\n<style>\n:root{color-scheme:light;--canvas:#f3f5f8;--surface:#fff;--text:#101a32;--muted:#59667e;--line:#dbe1e9;--soft:#f5f7fa;--blue:#245ed8;--selected:#edf4ff;--green:#137147;--green-bg:#e8f5ee;--amber:#915500;--amber-bg:#fff4db;--red:#a82d39;--red-bg:#ffedf0;--radius:7px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\n:root[data-theme=dark]{color-scheme:dark;--canvas:#111621;--surface:#181f2c;--text:#f0f3fa;--muted:#afbbd0;--line:#364052;--soft:#202938;--blue:#8cb7ff;--selected:#223751;--green:#8bdfb2;--green-bg:#173d31;--amber:#ffd58a;--amber-bg:#48351b;--red:#ffafba;--red-bg:#482932}\n*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--text);font-size:14px;line-height:1.5}button,select,textarea{font:inherit;color:inherit}button,select{min-height:40px;border:1px solid var(--line);border-radius:var(--radius);background:var(--surface)}button{cursor:pointer;padding:8px 15px}button:hover{background:var(--soft)}button:disabled{cursor:wait;opacity:.6}button:focus-visible,select:focus-visible,summary:focus-visible,textarea:focus-visible,a:focus-visible{outline:3px solid var(--blue);outline-offset:3px}h1,h2,h3,p{margin:0}button,select,textarea,h1,h2,p,dd,li{overflow-wrap:anywhere}h1{font-size:clamp(26px,3.2vw,40px);line-height:1.2;letter-spacing:-1.3px;font-weight:720}h2{font-size:24px;line-height:1.3;letter-spacing:-.5px}h3{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);font-weight:650;margin-bottom:10px;padding-bottom:6px;border-bottom:1px solid var(--line)}.shell{max-width:1440px;margin:0 auto;background:var(--surface);min-height:100vh;border-left:1px solid var(--line);border-right:1px solid var(--line)}.topbar{display:flex;align-items:center;gap:24px;padding:14px 28px;border-bottom:1px solid var(--line)}.brand{font-size:23px;font-weight:800;letter-spacing:-.7px}.board-name{padding-left:24px;border-left:1px solid var(--line);color:var(--muted);font-size:15px}.top-actions{margin-left:auto;display:flex;gap:16px;align-items:center}.quiet{color:var(--muted)}.demo{color:var(--amber);background:var(--amber-bg);padding:4px 9px;border-radius:4px;font-size:12px;font-weight:650}.intro{padding:30px 28px 24px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px 32px}.breadcrumb{margin-top:10px;color:var(--muted);font-size:15px}.contract-meta{display:grid;grid-template-columns:auto minmax(70px,180px);gap:5px 18px;margin:3px 0 0;align-content:start}.contract-meta dt{color:var(--muted)}.contract-meta dd{margin:0}.contract-context{grid-column:1/-1;font-size:13px;color:var(--muted)}summary{cursor:pointer;width:fit-content}details[open] summary{margin-bottom:8px}.context-body{border-left:2px solid var(--line);padding-left:12px;display:grid;gap:6px}.context-body ul{margin:0;padding-left:20px}.summary-band{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:17px 28px;gap:24px}.stat{border-right:1px solid var(--line);padding-left:10px}.stat:last-child{border:0}.stat strong{display:block;font-size:30px;line-height:1.25;letter-spacing:-.8px}.stat span{color:var(--muted)}.stat.accepted strong{color:var(--green)}.stat.review strong{color:var(--blue)}.stat.attention strong{color:var(--amber)}.workspace{display:grid;grid-template-columns:minmax(250px,31%) minmax(0,1fr);min-height:600px}.task-nav{border-right:1px solid var(--line)}.filter-wrap{padding:18px}.filter-wrap select{width:100%;padding:8px 12px}.task-list{list-style:none;margin:0;padding:0}.task-button{width:100%;text-align:left;border:none;border-bottom:1px solid var(--line);border-radius:0;padding:17px 22px 17px 25px;position:relative;min-height:90px}.task-button[aria-pressed=true]{background:var(--selected)}.task-button[aria-pressed=true]:before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--blue)}.task-title{font-size:15px;font-weight:650;display:block;margin-bottom:5px}.task-meta{font-size:12px;color:var(--muted);margin-top:6px;display:block}.status{display:inline-flex;align-items:center;gap:8px;font-size:13px;color:var(--muted)}.status:before{content:\"\";display:block;flex:none;width:9px;height:9px;border-radius:50%;background:currentColor}.status[data-status=accepted]{color:var(--green)}.status[data-status=checks_passed],.status[data-status=produced]{color:var(--blue)}.status[data-status=blocked],.status[data-status=stale]{color:var(--amber)}.status[data-status=rejected]{color:var(--red)}.detail{padding:24px 28px 30px;min-width:0}.detail-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.detail-head>div{min-width:0}.detail-head .status{margin-top:8px}.small-button{font-size:12px;white-space:nowrap;flex:none;min-height:36px;padding:7px 11px}.explanation{font-size:13px;color:var(--muted);margin-top:9px}.section{margin-top:22px}.criteria{padding-left:20px;margin:0}.criteria li{padding:2px 0}.criterion-kind{font-size:11px;color:var(--muted);margin-left:7px}.surface{background:var(--soft);border:1px solid var(--line);padding:12px 15px;border-radius:var(--radius);min-width:0}.surface+.surface{margin-top:8px}.artifact-path{font-weight:650}.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:11px;overflow-wrap:anywhere}.metadata{font-size:12px;color:var(--muted);margin-top:3px}.evidence-title{font-weight:600;font-size:13px}.evidence-note{margin-top:6px;font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}.outcome{color:var(--green)}.outcome.failed{color:var(--red)}.historical{border-left:3px solid var(--amber)}.historical-note{font-size:11px;color:var(--amber);margin-bottom:4px;font-weight:600}.empty{padding:20px;color:var(--muted);font-size:13px}.empty.large{padding:40px 4px}.notice{margin:0 28px 16px;padding:11px 14px;border-left:3px solid var(--amber);background:var(--amber-bg);color:var(--amber);font-size:13px}.notice[hidden],[hidden]{display:none!important}.detail-notice{margin:15px 0 0}.footer{border-top:1px solid var(--line);padding:12px 18px;display:flex;justify-content:space-between;gap:16px;color:var(--muted);font-size:11px;flex-wrap:wrap}.message{font-size:12px;color:var(--muted);margin-top:10px;min-height:18px}.handoff{width:100%;min-height:140px;margin-top:8px;border:1px solid var(--line);border-radius:var(--radius);padding:10px;background:var(--soft);font-family:ui-monospace,monospace;font-size:12px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.skip{position:absolute;top:-50px;left:10px;background:var(--surface);z-index:3;padding:8px}.skip:focus{top:10px}.loading{animation:breathe 1.4s ease-in-out infinite}@keyframes breathe{50%{opacity:.5}}@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important}}@media(max-width:760px){.topbar{padding:12px 18px;gap:14px}.board-name{padding-left:14px;font-size:13px}.top-actions{gap:10px}.read-only{display:none}.intro{padding:24px 20px 20px;grid-template-columns:minmax(0,1fr)}.contract-meta{grid-template-columns:auto 1fr;font-size:12px;gap:4px 14px}.summary-band{padding:14px 18px;gap:12px}.stat{padding-left:0}.stat strong{font-size:26px}.stat span{font-size:11px}.workspace{grid-template-columns:minmax(0,1fr);min-height:0}.task-nav{border-right:0;border-bottom:1px solid var(--line)}.task-list{max-height:270px;overflow:auto}.task-button{min-height:77px;padding:13px 20px}.filter-wrap{padding:14px 18px}.detail{padding:22px 20px 28px}.detail-head{flex-wrap:wrap}.detail-head h2{font-size:23px}.notice{margin-left:20px;margin-right:20px}.detail-notice{margin-left:0;margin-right:0}.contract-context{grid-column:auto}.footer{font-size:10px}.brand{font-size:21px}}@media(max-width:400px){.board-name{font-size:12px;max-width:85px;line-height:1.3}.topbar{gap:10px;padding-left:16px;padding-right:16px}.top-actions{gap:6px}.top-actions button{padding:7px 10px}.demo{font-size:10px;padding:3px 5px}.breadcrumb{font-size:12px}}\n</style>\n</head>\n<body>\n<a class=\"skip\" href=\"#task-detail\">Skip to task details</a>\n<div class=\"shell\">\n<header class=\"topbar\"><span class=\"brand\">rumbo</span><span class=\"board-name\">Acceptance board</span><div class=\"top-actions\"><span id=\"demo\" class=\"demo\" hidden>Demo</span><span class=\"quiet read-only\">Read only</span><button id=\"refresh\" type=\"button\">Refresh</button></div></header>\n<main>\n<section class=\"intro\" aria-labelledby=\"goal\"><div><h1 id=\"goal\">Loading your acceptance board</h1><p class=\"breadcrumb\">Goal → task → artifact → evidence → decision</p></div><dl class=\"contract-meta\"><dt>Contract revision</dt><dd id=\"contract-revision\">—</dd><dt>Decision owner</dt><dd id=\"decision-owner\">—</dd></dl><details class=\"contract-context\" id=\"contract-context\" hidden><summary>Original request &amp; constraints</summary><div id=\"context-body\" class=\"context-body\"></div></details></section>\n<div id=\"error\" class=\"notice\" role=\"alert\" hidden></div>\n<div id=\"integrity\" class=\"notice\" role=\"status\" hidden></div>\n<section class=\"summary-band\" aria-label=\"Task summary\"><div class=\"stat accepted\"><strong id=\"accepted-count\">0</strong><span>Accepted</span></div><div class=\"stat review\"><strong id=\"review-count\">0</strong><span>Ready for review</span></div><div class=\"stat attention\"><strong id=\"attention-count\">0</strong><span>Needs attention</span></div></section>\n<div class=\"workspace\"><nav class=\"task-nav\" aria-label=\"Tasks\"><div class=\"filter-wrap\"><label for=\"status-filter\" class=\"sr-only\">Filter tasks</label><select id=\"status-filter\"><option value=\"all\">All tasks</option><option value=\"review\">Ready for review</option><option value=\"attention\">Needs attention</option><option value=\"accepted\">Accepted</option><option value=\"active\">In progress</option></select></div><ul id=\"task-list\" class=\"task-list\"></ul><p id=\"list-empty\" class=\"empty\" hidden>No tasks yet</p></nav><article id=\"task-detail\" class=\"detail\" aria-label=\"Task details\" tabindex=\"-1\"><p class=\"empty large loading\" id=\"loading\">Waiting for the project snapshot…</p></article></div>\n</main><footer class=\"footer\"><span id=\"connection\">Connecting…</span><span id=\"ledger\">Read-only view · Decisions stay with the named owner</span></footer>\n</div>\n<script>\n(() => {\n'use strict';\nconst $ = id => document.getElementById(id);\nconst labels = {unclaimed:'Unclaimed', claimed:'Claimed', blocked:'Blocked', produced:'Produced', checks_passed:'Checks passed', accepted:'Accepted', rejected:'Rejected', stale:'Stale'};\nconst attention = new Set(['blocked','rejected','stale']);\nconst embedded = window.parent !== window;\nconst pending = new Map();\nlet state = null, selected = null, ready = false, canRefresh = false, hostOrigin = null;\nlet requestSequence = 0, resizeTimer = null, lastSize = '', hostContext = {}, closed = false;\nconst protocolVersion = '2026-01-26';\nconst text = value => value == null ? '—' : typeof value === 'object' ? JSON.stringify(value, null, 2) : String(value);\nconst array = value => Array.isArray(value) ? value : [];\nfunction element(tag, value, className) {\n  const node = document.createElement(tag);\n  if (value != null) node.textContent = text(value);\n  if (className) node.className = className;\n  return node;\n}\nfunction statusNode(status) {\n  const node = element('span', labels[status] || 'Unknown status', 'status');\n  node.dataset.status = Object.hasOwn(labels, status) ? status : 'unknown';\n  return node;\n}\nfunction date(value) {\n  if (value == null) return 'Time not recorded';\n  const valueDate = new Date(typeof value === 'number' ? value * 1000 : value);\n  return Number.isNaN(valueDate.getTime()) ? text(value) : valueDate.toLocaleString();\n}\nfunction error(message) {\n  $('error').textContent = message + (state ? ' Showing the last snapshot; it may be out of date.' : ' No project snapshot is available.');\n  $('error').hidden = false;\n  $('connection').textContent = embedded ? 'Host connection needs attention' : 'Hosted connection needs attention';\n  $('refresh').disabled = false;\n  $('refresh').textContent = 'Refresh';\n  if (!state) {\n    $('goal').textContent = 'Your acceptance board';\n    $('task-detail').replaceChildren(element('p','Refresh to try again. In an MCP host, open the Rumbo board tool to load a project.','empty large'));\n  }\n}\nfunction matches(task, filter) {\n  return filter === 'all' || (filter === 'review' && task.status === 'checks_passed') ||\n    (filter === 'attention' && attention.has(task.status)) || (filter === 'accepted' && task.status === 'accepted') ||\n    (filter === 'active' && ['unclaimed','claimed','produced'].includes(task.status));\n}\nfunction renderList() {\n  const tasks = state.tasks.filter(task => matches(task, $('status-filter').value));\n  const fragment = document.createDocumentFragment();\n  for (const task of tasks) {\n    const li = element('li');\n    const button = element('button',null,'task-button');\n    button.type = 'button';\n    button.setAttribute('aria-pressed', String(selected === task.id));\n    button.append(element('span',task.title || task.id,'task-title'),statusNode(task.status));\n    if (task.lease && task.status === 'claimed') button.append(element('span','Claimed by ' + text(task.lease.actor),'task-meta'));\n    button.addEventListener('click', () => { selected = task.id; renderList(); renderDetail(); });\n    li.append(button); fragment.append(li);\n  }\n  $('task-list').replaceChildren(fragment);\n  $('list-empty').hidden = tasks.length > 0;\n  $('list-empty').textContent = state.tasks.length ? 'No tasks match this filter' : 'No tasks yet';\n}\nfunction section(title) {\n  const node = element('section',null,'section');\n  node.append(element('h3',title));\n  return node;\n}\nfunction historical(record, task) {\n  return record.contract_revision !== state.contract_revision || record.artifact_revision !== task.artifact?.revision || (record.artifact_sha256 != null && record.artifact_sha256 !== task.artifact?.sha256);\n}\nfunction receipt(record, task, assertion) {\n  const old = historical(record, task);\n  const latest = array(task.evidence).filter(e => e.check_id === record.check_id && !historical(e,task)).at(-1);\n  const superseded = !old && latest && latest !== record;\n  const card = element('div',null,'surface' + (old ? ' historical' : ''));\n  if (old) card.append(element('p','Historical · does not apply to the current artifact and contract','historical-note'));\n  else if (superseded) card.append(element('p','Superseded receipt · a later record exists for this check','historical-note'));\n  const passed = ['pass','passed','accepted','accept'].includes(record.outcome);\n  card.append(element('p',text(record.outcome) + ' · ' + text(record.check_id || record.kind),'evidence-title outcome' + (passed ? '' : ' failed')));\n  if (record.detail != null) card.append(element('p',record.detail,'evidence-note' + (typeof record.detail === 'object' ? ' mono' : '')));\n  card.append(element('p',(assertion ? 'Assertion by ' : 'Recorded by ') + text(record.actor) + ' · ' + text(record.role || 'role not recorded'),'metadata'));\n  card.append(element('p','Artifact r' + text(record.artifact_revision) + ' · contract r' + text(record.contract_revision) + ' · ' + date(record.at),'metadata'));\n  return card;\n}\nfunction handoff(task) {\n  const lines = [state.demo ? 'Rumbo DEMO handoff' : 'Rumbo handoff', 'Goal: ' + text(state.goal),\n    'Project: ' + text(state.project_id), 'Contract: r' + text(state.contract_revision),\n    'Task: ' + text(task.id) + ' — ' + text(task.title), 'State: ' + (labels[task.status] || text(task.status)),\n    'Decision owner: ' + text(state.decision_owner), 'Artifact: ' + (task.artifact ? text(task.artifact.path) + ' (r' + text(task.artifact.revision) + ', SHA256 ' + text(task.artifact.sha256) + ')' : 'None'),\n    'Deterministic receipts: ' + array(task.evidence).filter(e => e.kind === 'deterministic').length,\n    'Reviewer assertions: ' + array(task.evidence).filter(e => e.kind === 'reviewer_assertion').length,\n    'Human decisions recorded: ' + array(task.decisions).length];\n  if (task.stale_reason) lines.push('Attention: ' + text(task.stale_reason));\n  lines.push('Receipt/assertion/decision counts include history. Checks passed is not acceptance.',\n    'Ledger head: ' + text(state.ledger_head), 'Ledger integrity: ' + (state.integrity?.valid === true ? 'verified by hosted runtime' : 'not verified'));\n  return lines.join('\\n');\n}\nasync function copyHandoff(task) {\n  const summary = handoff(task);\n  try {\n    if (!navigator.clipboard?.writeText) throw new Error('Clipboard unavailable');\n    await navigator.clipboard.writeText(summary);\n    $('message').textContent = 'Copied handoff summary';\n  } catch (_) {\n    $('handoff-text').value = summary; $('handoff-text').hidden = false;\n    $('handoff-text').focus(); $('handoff-text').select();\n    $('message').textContent = 'Select and copy the handoff summary below';\n  }\n}\nfunction renderDetail() {\n  const root = $('task-detail');\n  const task = state.tasks.find(item => item.id === selected);\n  if (!task) { root.replaceChildren(element('p',state.tasks.length ? 'Select a task to follow its evidence trail.' : 'Your goal is ready. Add tasks with explicit acceptance criteria to start the trail.','empty large')); return; }\n  const frag = document.createDocumentFragment();\n  const head = element('div',null,'detail-head'), title = element('div');\n  title.append(element('h2',task.title || task.id), statusNode(task.status));\n  const copy = element('button','Copy handoff','small-button'); copy.type = 'button';\n  copy.addEventListener('click',() => copyHandoff(task)); head.append(title, copy); frag.append(head);\n  frag.append(element('p','Checks passed is not acceptance. The decision belongs to ' + text(state.decision_owner) + '.','explanation'));\n  if (task.stale_reason) frag.append(element('p',task.stale_reason,'notice detail-notice'));\n  if (task.lease) frag.append(element('p','Lease: ' + text(task.lease.actor) + ' · expires ' + date(task.lease.expires_at),'metadata'));\n  if (array(task.dependencies).length) frag.append(element('p','Depends on: ' + task.dependencies.map(text).join(', '),'metadata'));\n  const criteria = section('Acceptance criteria');\n  if (!array(task.acceptance).length) criteria.append(element('p','No acceptance criteria recorded','quiet'));\n  else {\n    const list = element('ol',null,'criteria');\n    for (const check of task.acceptance) {\n      const li = element('li',check.description || check.title || check.id);\n      li.append(element('span',check.kind,'criterion-kind'));\n      if (check.prompt) li.append(element('p',check.prompt,'metadata'));\n      if (Object.hasOwn(check,'key')) li.append(element('p','Key: ' + text(check.key),'metadata mono'));\n      if (Object.hasOwn(check,'value')) li.append(element('p','Expected: ' + text(check.value),'metadata mono'));\n      list.append(li);\n    }\n    criteria.append(list);\n  }\n  frag.append(criteria);\n  const artifact = section('Artifact');\n  if (task.artifact) {\n    const box = element('div',null,'surface');\n    box.append(element('p',task.artifact.path,'artifact-path'),\n      element('p','Revision ' + text(task.artifact.revision) + ' · ' + text(task.artifact.size) + ' bytes · maker ' + text(task.artifact.maker),'metadata'),\n      element('p','SHA256: ' + text(task.artifact.sha256),'metadata mono'));\n    box.append(element('p',task.artifact.source === 'uploaded_text' ? 'Uploaded text: received bytes only; no Git or repository authenticity implied.' : 'Registered project file: exact bytes from the configured root.','metadata'));\n    artifact.append(box);\n  } else artifact.append(element('p','No artifact submitted','quiet'));\n  frag.append(artifact);\n  const groups = [ ['Deterministic receipts', e => e.kind === 'deterministic', false, 'No deterministic receipts recorded'],\n    ['Reviewer assertions', e => e.kind === 'reviewer_assertion', true, 'No reviewer assertions recorded'] ];\n  for (const [name, include, assertion, empty] of groups) {\n    const group = section(name), records = array(task.evidence).filter(include);\n    if (assertion) group.append(element('p','Attributed reviewer statements; not deterministic proof.','explanation'));\n    for (const record of records) group.append(receipt(record,task,assertion));\n    if (!records.length) group.append(element('p',empty,'quiet'));\n    frag.append(group);\n  }\n  const unknown = array(task.evidence).filter(e => !['deterministic','reviewer_assertion'].includes(e.kind));\n  if (unknown.length) {\n    const group = section('Other recorded evidence');\n    group.append(element('p','Unrecognized evidence kind; no proof classification is assumed.','quiet'));\n    for (const record of unknown) group.append(receipt(record,task,true));\n    frag.append(group);\n  }\n  const decisions = section('Human decision');\n  if (!array(task.decisions).length) decisions.append(element('p','Awaiting ' + text(state.decision_owner),'surface'));\n  for (const record of array(task.decisions)) {\n    const old = historical(record,task), card = element('div',null,'surface' + (old ? ' historical' : ''));\n    if (old) card.append(element('p','Historical decision · does not apply to the current revision','historical-note'));\n    else if (record !== array(task.decisions).filter(d => !historical(d,task)).at(-1)) card.append(element('p','Superseded decision · a later decision exists','historical-note'));\n    if (!old && ['accepted','accept'].includes(record.outcome) && task.status !== 'accepted') card.append(element('p','Not current acceptance · evidence or dependency state changed; a new owner decision is needed.','historical-note'));\n    card.append(element('p',text(record.outcome) + ' · ' + text(record.actor),'evidence-title'));\n    card.append(element('p',record.reason,'evidence-note'));\n    card.append(element('p','Artifact r' + text(record.artifact_revision) + ' · contract r' + text(record.contract_revision) + ' · ' + date(record.at),'metadata'));\n    decisions.append(card);\n  }\n  frag.append(decisions);\n  const requests = array(state.requests).filter(r => r.task_id === task.id);\n  if (requests.length) {\n    const group = section('Recorded decision requests');\n    group.append(element('p','Questions recorded for the owner. A request is not a decision; resolution is not tracked separately.','explanation'));\n    for (const record of requests) {\n      const card = element('div',null,'surface');\n      if (record.contract_revision !== state.contract_revision) card.append(element('p','Historical request · prior contract revision','historical-note'));\n      card.append(element('p',record.question,'evidence-note'),element('p',text(record.actor) + ' · contract r' + text(record.contract_revision) + ' · ' + date(record.at),'metadata'));\n      group.append(card);\n    }\n    frag.append(group);\n  }\n  const message = element('p',null,'message');message.id = 'message';message.setAttribute('aria-live','polite');\n  const handoffText = element('textarea',null,'handoff');handoffText.id = 'handoff-text';handoffText.readOnly = true;handoffText.hidden = true;handoffText.setAttribute('aria-label','Handoff summary');\n  frag.append(message,handoffText);root.replaceChildren(frag);\n}\nfunction render(snapshot) {\n  if (snapshot?.project_selection_required && Array.isArray(snapshot.projects)) {\n    state = null; selected = null; $('goal').textContent = 'Choose your project';\n    $('task-list').replaceChildren(); $('task-detail').replaceChildren(); $('error').hidden = true;\n    $('accepted-count').textContent = '0'; $('review-count').textContent = '0'; $('attention-count').textContent = '0';\n    $('contract-revision').textContent = '—'; $('decision-owner').textContent = '—';\n    $('contract-context').hidden = true; $('integrity').hidden = true; $('demo').hidden = true;\n    for (const project of snapshot.projects) {\n      const button = element('button', project.alias + ' · ' + project.role, 'task-button'); button.type = 'button';\n      button.addEventListener('click', async () => { try { consume(await request('tools/call', {name:'rumbo_state',arguments:{project_key:project.project_key}})); } catch (e) { error(e.message); } });\n      $('task-list').append(button);\n    }\n    $('task-detail').append(element('p', snapshot.projects.length ? 'Select an authorized project to inspect its exact evidence.' : 'No authorized projects yet. Create a contract in the signed-in owner browser.', 'empty large'));\n    $('connection').textContent = 'Authorized project selector'; $('ledger').textContent = 'Read-only project selection';\n    $('refresh').disabled = true; return;\n  }\n\n  if (!snapshot || snapshot.version !== 1 || !Array.isArray(snapshot.tasks) || typeof snapshot.goal !== 'string' || snapshot.tasks.some(t => !t || typeof t.id !== 'string')) throw new Error('Unsupported or malformed project snapshot');\n  state = snapshot;\n  if (!state.tasks.some(task => task.id === selected)) selected = state.tasks[0]?.id || null;\n  $('goal').textContent = state.goal || 'Untitled goal';\n  $('contract-revision').textContent = text(state.contract_revision);\n  $('decision-owner').textContent = text(state.decision_owner);\n  $('demo').hidden = state.demo !== true;\n  $('error').hidden = true;\n  $('accepted-count').textContent = String(state.tasks.filter(t => t.status === 'accepted').length);\n  $('review-count').textContent = String(state.tasks.filter(t => t.status === 'checks_passed').length);\n  $('attention-count').textContent = String(state.tasks.filter(t => attention.has(t.status)).length);\n  const context = $('context-body');context.replaceChildren();\n  if (state.original_request) context.append(element('p',state.original_request));\n  if (array(state.constraints).length) {const list = element('ul');for(const constraint of state.constraints)list.append(element('li',constraint));context.append(list);}\n  $('contract-context').hidden = !context.childNodes.length;\n  const integrity = state.integrity?.valid === true;\n  $('integrity').hidden = integrity;\n  $('integrity').textContent = 'Ledger integrity is not verified. Treat the recorded statuses as untrusted until the ledger is checked.';\n  $('ledger').textContent = text(state.events_count) + ' ledger events · ' + (integrity ? 'Hash chain verified by hosted runtime' : 'Integrity not verified');\n  $('ledger').title = 'Ledger head: ' + text(state.ledger_head) + '. A stored hash chain does not prove real-world correctness.';\n  $('connection').textContent = (embedded ? 'MCP host snapshot' : 'Hosted snapshot') + (state.demo ? ' · demonstration data' : '') + ' · refreshed ' + new Date().toLocaleTimeString();\n  renderList();renderDetail();\n  $('refresh').disabled = embedded && !canRefresh;\n  $('refresh').textContent = 'Refresh';\n}\nfunction consume(result) {\n  const payload = result?.result || result;\n  if (payload?.isError) throw new Error('The host reported a tool error');\n  render(payload?.structuredContent);\n}\nfunction post(message) {\n  if (!closed) window.parent.postMessage(message, hostOrigin && hostOrigin !== 'null' ? hostOrigin : '*');\n}\nfunction notify(method, params = {}) { post({jsonrpc:'2.0',method,params}); }\nfunction request(method, params) {\n  return new Promise((resolve,reject) => {\n    const id = 'rumbo-' + (++requestSequence);\n    const timeout = setTimeout(() => {pending.delete(id);reject(new Error('Host request timed out'));},10000);\n    pending.set(id,{resolve,reject,timeout});post({jsonrpc:'2.0',id,method,params});\n  });\n}\nfunction applyContext(update) {\n  hostContext = {...hostContext,...update};\n  document.documentElement.dataset.theme = hostContext.theme === 'dark' ? 'dark' : 'light';\n  // Host CSS and font payloads are deliberately not injected: this app needs no network assets.\n}\nfunction sizeChanged() {\n  clearTimeout(resizeTimer);\n  resizeTimer = setTimeout(() => {\n    if (!ready || closed) return;\n    const width = Math.ceil(document.documentElement.getBoundingClientRect().width);\n    const height = Math.ceil(document.body.getBoundingClientRect().height);\n    const signature = width + ':' + height;\n    if (signature !== lastSize) {lastSize = signature;notify('ui/notifications/size-changed',{width,height});}\n  },70);\n}\nfunction onMessage(event) {\n  if (event.source !== window.parent || !embedded || closed) return;\n  if (hostOrigin !== null && event.origin !== hostOrigin) return;\n  const message = event.data;\n  if (!message || typeof message !== 'object' || message.jsonrpc !== '2.0') return;\n  if (Object.hasOwn(message,'id') && pending.has(message.id)) {\n    const call = pending.get(message.id);pending.delete(message.id);clearTimeout(call.timeout);\n    if (hostOrigin === null) hostOrigin = event.origin;\n    if (message.error) call.reject(new Error(text(message.error.message)));\n    else call.resolve(message.result);\n    return;\n  }\n  if (!ready) return;\n  try {\n    if (message.method === 'ui/notifications/tool-result') consume(message.params);\n    else if (message.method === 'ui/notifications/host-context-changed') applyContext(message.params || {});\n    else if (message.method === 'ui/notifications/tool-cancelled') error('The tool call was cancelled.');\n    else if (message.method === 'ping' && Object.hasOwn(message,'id')) post({jsonrpc:'2.0',id:message.id,result:{}});\n    else if (message.method === 'ui/resource-teardown' && Object.hasOwn(message,'id')) {\n      post({jsonrpc:'2.0',id:message.id,result:{}});closed = true;\n      clearTimeout(resizeTimer);observer?.disconnect();window.removeEventListener('message',onMessage);\n      for (const call of pending.values()) {clearTimeout(call.timeout);call.reject(new Error('View closed'));}pending.clear();\n    }\n  } catch (err) {error(err.message);}\n}\nasync function initialize() {\n  $('refresh').disabled = true;\n  try {\n    const result = await request('ui/initialize',{appInfo:{name:'Rumbo acceptance board',version:'0.1.0'},appCapabilities:{availableDisplayModes:['inline']},protocolVersion});\n    if (result?.protocolVersion !== protocolVersion) throw new Error('The host does not support MCP Apps protocol ' + protocolVersion);\n    canRefresh = !!result.hostCapabilities?.serverTools;\n    applyContext(result.hostContext || {});ready = true;\n    notify('ui/notifications/initialized');sizeChanged();\n    $('refresh').disabled = !canRefresh;\n    $('refresh').title = canRefresh ? 'Read the latest project state' : 'This host does not provide tool refresh';\n    $('connection').textContent = 'Connected to MCP host · waiting for its initial tool result';\n    // The initial state arrives from the host. Do not issue a duplicate tools/call.\n  } catch (err) {error(err.message);}\n}\nasync function refresh() {\n  $('refresh').disabled = true;$('refresh').textContent = 'Refreshing…';\n  try {\n    if (embedded) {\n      if (!ready) {await initialize();return;}\n      if (!canRefresh) throw new Error('The host does not support tool refresh');\n      consume(await request('tools/call',{name:'rumbo_state',arguments:{project_key:state?.hosted_project_key}}));\n    } else {\n      const controller = new AbortController(), timer = setTimeout(() => controller.abort(),10000);\n      try {\n        const response = await fetch('/api/state'+window.location.search,{cache:'no-store',credentials:'omit',signal:controller.signal});\n        if (!response.ok) throw new Error('Cannot read local project state (HTTP ' + response.status + ')');\n        render(await response.json());\n      } finally {clearTimeout(timer);}\n    }\n  } catch (err) {error(err.name === 'AbortError' ? 'The local request timed out.' : err.message);}\n}\n$('status-filter').addEventListener('change',() => { if (state) renderList(); });\n$('refresh').addEventListener('click',refresh);\nlet observer = null;\nif (embedded) {\n  window.addEventListener('message',onMessage);\n  if (typeof ResizeObserver !== 'undefined') {observer = new ResizeObserver(sizeChanged);observer.observe(document.body);}\n  initialize();\n} else refresh();\n})();\n</script>\n</body>\n</html>\n";
